-- The anime cards show the sharper pictures kept with the Mini App under
-- public/kartalar/art: each AniList picture upscaled four times by
-- Real-ESRGAN's anime model and kept at 600 by 900, the same art, served by
-- Vercel's CDN. A card whose picture was chosen by hand from MyAnimeList
-- keeps it. The path is the bot's own, which the Mini App opens as it is and
-- the bot fetches from its site; card_pictures keeps it through a refresh of
-- the catalog.
INSERT INTO card_pictures (card_id, image_url)
SELECT c.id, '/kartalar/art/' || c.id || '.jpg'
FROM card_catalog c
WHERE c.image_url LIKE '%anilist%' AND c.id IN (
    2, 7, 15, 16, 18, 19, 29, 40, 63, 64, 70, 75, 85, 89, 162, 183, 208, 210, 
    245, 246, 251, 306, 309, 310, 369, 390, 417, 423, 425, 434, 496, 497, 500, 
