ON CONFLICT (card_id) DO NOTHING;

UPDATE card_catalog c
SET image_url = p.image_url, updated_at = now()
FROM card_pictures p
WHERE p.card_id = c.id AND p.image_url LIKE '/kartalar/art/%' AND c.image_url <> p.image_url;
